export const PREDICATE_NAMES = Object.freeze(Object.keys(PREDICATES));

/** Entity kinds used by `entity.kind`. */
export const ENTITY_KINDS = Object.freeze([
	"self",
	"person",
	"org",
	"project",
	"place",
	"device",
	"account",
	"other",
]);

/**
 * Look up a predicate definition.
 * @param {string} name - predicate name.
 * @returns {typeof PREDICATES[string] | null} definition or null.
 */
export function predicateSpec(name) {
	return Object.prototype.hasOwnProperty.call(PREDICATES, name) ? PREDICATES[name] : null;
}

/**
 * One-line list for error messages and the tool description.
 * @returns {string} comma-separated names.
 */
export function predicateList() {
	return PREDICATE_NAMES.join(", ");
}

/**
 * Describe the vocabulary compactly for the model-facing tool description.
 * @returns {string} multi-line list with kind/cardinality/pinned markers.
 */
export function describePredicates() {
	return PREDICATE_NAMES.map((name) => {
		const spec = PREDICATES[name];
		const flags = [spec.kind, spec.cardinality, spec.pinned ? "pinned" : ""]
			.filter((part) => part.length > 0)
			.join("/");
		return `${name} (${flags})`;
	}).join("; ");
}
